IVE</option></select></div><div class="col-md-6"><label class="form-label">Image (JPG/PNG/WebP, 2 Mo max)</label><input type="file" class="form-control" name="image" accept="image/jpeg,image/png,image/webp"></div><div class="col-12"><button class="btn btn-km">Enregistrer</button><?php if($product):?><a class="btn btn-outline-dark ms-2" target="_blank" href="<?=e(base_url('products/'.$p['id'].'/label'))?>">Étiquette code-barres</a><button form="deleteForm" class="btn btn-outline-danger ms-2" type="button" onclick="if(confirm('Archiver ce produit ?'))document.getElementById('deleteForm').submit()">Archiver</button><?php endif;?></div></div></form><?php if($product):?><form id="deleteForm" method="post" action="<?=e(base_url('products/'.$p['id'].'/delete'))?>" class="d-none"><?=csrf_field()?></form><?php endif;?>